const PANELS={files:['Proje dosyaları','.file-panel'],library:['Bileşen kütüphanesi','.library-panel'],parts:['Devre elemanları','.components-panel'],circuit:['Devre','.circuit-panel'],code:['Kod editörü','.code-panel'],terminal:['Terminal','.terminal-panel'],properties:['Özellikler','.inspector-panel'],measurement:['Ölçüm / analizör','.instrument-panel'],pinout:['Kart pinout','.gpio-panel']};
const KEY='circuitforge.windows.v1';
export function normalizeLayout(raw={}){const panels=Object.fromEntries(Object.keys(PANELS).map(k=>[k,typeof raw?.panels?.[k]==='boolean'?raw.panels[k]:true]));if(!panels.circuit&&!panels.code&&!panels.terminal)panels.circuit=true;return{panels,left:Math.max(145,Math.min(420,Number(raw?.left)||194)),right:Math.max(180,Math.min(420,Number(raw?.right)||263)),canvas:Math.max(25,Math.min(75,Number(raw?.canvas)||58)),code:Math.max(25,Math.min(75,Number(raw?.code)||62))};}
export function installWindowLayout({onResize=()=>{}}={}){
 const $=s=>document.querySelector(s),root=$('.workspace');let state;try{state=normalizeLayout(JSON.parse(localStorage.getItem(KEY)||'{}'));}catch{state=normalizeLayout();}
 const menu=document.createElement('div');menu.id='window-menu';menu.hidden=true;menu.className='window-menu';menu.setAttribute('aria-label','Pencere düzeni');$('#windows-menu').after(menu);const close=()=>{menu.hidden=true;$('#windows-menu').setAttribute('aria-expanded','false');};
 document.documentElement.style.setProperty('--canvas-share',state.canvas+'%');document.documentElement.style.setProperty('--code-share',state.code+'%');
 const render=()=>{menu.innerHTML=`<div class="window-presets"><button data-preset="circuit">Devre + kütüphane</button><button data-preset="code">Kod + terminal</button><button data-preset="all">Tüm paneller</button></div>${Object.entries(PANELS).map(([k,[name]])=>`<label><input type="checkbox" data-panel="${k}" ${state.panels[k]?'checked':''}>${name}</label>`).join('')}<button id="window-default">Varsayılan düzen</button>`;};
 const apply=(save=true)=>{for(const[k,[,selector]]of Object.entries(PANELS))$(selector).hidden=!state.panels[k];const left=state.panels.files||state.panels.library||state.panels.parts,right=state.panels.properties||state.panels.measurement||state.panels.pinout,bottom=state.panels.code||state.panels.terminal;
  $('.sidebar').hidden=!left;$('.rightbar').hidden=!right;$('#left-resizer').hidden=!left;$('#right-resizer').hidden=!right;$('.bottom-panes').hidden=!bottom;$('#row-resizer').hidden=!(state.panels.circuit&&bottom);$('#column-resizer').hidden=!(state.panels.code&&state.panels.terminal);
  root.style.gridTemplateColumns=`${left?Math.min(state.left,innerWidth*.3):0}px ${left?5:0}px minmax(0,1fr) ${right?5:0}px ${right?Math.min(state.right,innerWidth*.3):0}px`;
  $('.center').style.gridTemplateRows=state.panels.circuit&&bottom?'minmax(120px,var(--canvas-share)) 5px minmax(100px,1fr)':'minmax(0,1fr)';$('.bottom-panes').style.gridTemplateColumns=state.panels.code&&state.panels.terminal?'minmax(100px,var(--code-share)) 5px minmax(100px,1fr)':'minmax(0,1fr)';root.classList.toggle('only-library',left&&!state.panels.files&&!state.panels.parts);
  $('.sidebar').classList.toggle('only-parts',left&&state.panels.parts&&!state.panels.files&&!state.panels.library);$('.rightbar').classList.toggle('only-properties',right&&state.panels.properties&&!state.panels.measurement&&!state.panels.pinout);
  if(save)try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}render();requestAnimationFrame(onResize);
 };
 $('#windows-menu').onclick=()=>{menu.hidden=!menu.hidden;$('#windows-menu').setAttribute('aria-expanded',String(!menu.hidden));};
 menu.onchange=e=>{if(e.target.dataset.panel){state.panels[e.target.dataset.panel]=e.target.checked;state=normalizeLayout(state);apply();}};
 menu.onclick=e=>{const preset=e.target.dataset.preset;if(preset){const shown=preset==='all'?Object.keys(PANELS):preset==='circuit'?['library','circuit']:['code','terminal'];state.panels=Object.fromEntries(Object.keys(PANELS).map(k=>[k,shown.includes(k)]));apply();close();}if(e.target.id==='window-default')reset();};
 document.addEventListener('pointerdown',e=>{if(!menu.contains(e.target)&&e.target!==$('#windows-menu'))close();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu.hidden){close();$('#windows-menu').focus();}});
 const reset=()=>{state=normalizeLayout();document.documentElement.style.setProperty('--canvas-share',state.canvas+'%');document.documentElement.style.setProperty('--code-share',state.code+'%');apply();close();};
 for(const [id,key,variable]of[['row-resizer','canvas','--canvas-share'],['column-resizer','code','--code-share']])$('#'+id).addEventListener('pointerup',()=>{state[key]=parseFloat(document.documentElement.style.getPropertyValue(variable))||state[key];apply();});
 for(const side of ['left','right'])$('#'+side+'-resizer').onpointerdown=e=>{const node=e.currentTarget;node.setPointerCapture(e.pointerId);const start=e.clientX,width=state[side];node.onpointermove=m=>{state[side]=Math.max(side==='left'?145:180,Math.min(420,width+(m.clientX-start)*(side==='left'?1:-1)));apply(false);};node.onpointerup=()=>{node.onpointermove=null;apply();};node.onpointercancel=()=>{node.onpointermove=null;apply();};};
 addEventListener('resize',()=>apply(false));apply(false);return{reset};
}
